LINKS = []
SHARES = []


def entities(E):
    LINKS.clear(); SHARES.clear(); out=[]
    def add(s,kind,key,n,en,q,eq,cn='',note='',**extra):
        suffix=s[4:]+s[1:3] if s.startswith('r') else s
        out.append(E(s,kind,key+'-'+suffix,n,en,q,cn or '经文、郭注引说与项目解释分层保存，原名、方位和数量不换算为现代物种或坐标。',eq,(eq+' '+note).strip(),**extra))
        return out[-1]['id']
    def product(s,key,n,en,q,eq,kind='material',**extra):
        row=next(r for r in ROWS if r['slug']==s)
        return add(s,kind,key,n+'（'+row['name']+'）',en+' ('+row['en_name']+')',q,eq,**extra)
    def products(s,items):
        for k,n,en,q,eq in items:product(s,k,n,en,q,eq)
    def plants(s,items,q):
        for k,n,en in items:product(s,k,n,en,q,en+' are listed here.','plant')
    def unknown(s,key,n,en,q,kind='animal',eq=None,**extra):
        return add(s,kind,key,n,en,q,eq or en+' are recorded here.','独立完整形貌不足，仅保留原名、数量与经注层次；占位不代表真实形态，不借同名他篇补形。','Insufficient independent complete form evidence; the placeholder supplies no invented portrait.',unknown=True,**extra)
    def water(s,key,n,en,q,eq,**extra):return add(s,'water',key,n,en,q,eq,'按本段的渊、水、会通或空间叙述存录，不换算现代河道、湖泊边界或坐标。',**extra)
    def rite(s,key,n,en,q,eq,**extra):return add(s,'rite',key,n,en,q,eq,'一般礼与专祀、经文与郭注分存，祭牲与山神形貌分开；不扩写现实操作规程。',**extra)

    s='r11-summary'
    add(s,'deity','humanhead-pig','次十一山神（彘身人首）','Eleventh-range gods (pig body, human head)','其神狀皆彘身人首','The gods have pig bodies and human heads.','彘身人首据正文，图保留完整猪躯配人头；四蹄、耳发须、毛色与姿态为艺术解释，不画人躯猪头。','Four hooves, human hair/beard, coat colors and pose are artistic; no human torso or pig snout replaces the stated body plan.')
    for k,n,en,q,eq in [('rooster','雄雞','Rooster offering','其祠毛用一雄雞祈瘞','The general rite uses one rooster, prayer and burial.'),('gui','珪','Gui jade','用一珪','One gui jade is used.'),('grain','五種之精','Five refined grains','糈用五種之精','Five kinds of refined grain are used.'),('he','禾山帝专祀','He imperial rite','禾山帝也其祠太牢之具羞瘞倒毛用一璧牛無常','He has an imperial rite with greater livestock, offerings, burial, inversion and a bi jade; the cattle wording does not fix a number.'),('du-yu','堵山玉山冢专祀','Du and Yu principal-mountain rites','堵山玉山冢也皆倒祠羞毛少牢嬰毛吉玉','Du and Yu have inverted-offering rites with lesser livestock and jade.')]:rite(s,k,n+'（次十一总括）',en+' (eleventh summary)',q,eq)
    s='r12-pianyu';product(s,'gold','黃金','Gold','多黃金','Gold is abundant.')
    s='r12-yun'
    product(s,'gui-bamboo','桂竹','Gui bamboo','有桂竹甚毒傷人必死','Gui bamboo is recorded with an ancient severe-poison claim.','plant')
    add(s,'plant','gui-comparison','筀竹（始兴郭注比较）','Gui bamboo (Shixing commentary comparison)','今始興郡桂陽縣出筀竹大者圍二尺長四丈','The commentary records external Gui bamboo at historical Guiyang, large examples two chi in girth and four zhang long.','郭注外地比较，尺寸与竹名照存，不当雲山当地实测或现代种属。',commentary_only=True,comparison_only=True)
    add(s,'plant','li-comparison','篥竹（交趾郭注比较）','Li bamboo (Jiaozhi commentary comparison)','又交趾有篥竹實中勁强有毒','The commentary also records external Li bamboo at Jiaozhi, solid, strong and described as poisonous.','郭注外地比较，不移作雲山本地竹种；古毒性与伤虎说保留于完整郭注，不作使用指引。',commentary_only=True,comparison_only=True)
    products(s,[('gold','黃金','Gold','其上多黃金','Gold is abundant above.'),('tufu','㻬琈之玉','Tufu jade','其下多㻬琈之玉','Tufu jade is abundant below.')])
    s='r12-gui';plants(s,[('gu','榖','Gu trees'),('zuo','柞','Zuo trees'),('chou','椆','Chou trees'),('ju','椐','Ju trees')],'其木多榖柞椆椐');products(s,[('gold','黄金','Gold','其上多黄金','Gold is abundant above.'),('qing-xionghuang','青雄黃','Qing-xionghuang','其下多青雄黃','Qing-xionghuang is abundant below.')])
    product(s,'fu-bamboo','扶竹','Fu bamboo','多扶竹','Fu bamboo is abundant.','plant',commentary='卭竹也髙節實中中杖也名之扶老竹',en_commentary='Qiong bamboo, high-jointed and solid inside, historically used for staffs and also called Fulao.')
    s='r12-bing';plants(s,[('gui-bamboo','筀竹','Gui bamboo')],'多筀竹');products(s,[('gold','黄金','Gold','多黄金銅鐵','Gold is abundant.'),('copper','銅','Copper','多黄金銅鐵','Copper is abundant.'),('iron','鐵','Iron','多黄金銅鐵','Iron is abundant.')])
    s='r12-fengbo';products(s,[('gold','金','Gold','其上多金玉','Gold is abundant above.'),('jade','玉','Jade','其上多金玉','Jade is abundant above.'),('patterned-stone','文石','Patterned stone','文石多鐵','Patterned stone is listed below.'),('iron','鐵','Iron','多鐵','Iron is abundant.')]);product(s,'suan-stone','痠石','Suan stone','其下多痠石','Suan stone is abundant below.',commentary='未詳痠石之義',en_commentary='Guo Pu leaves the meaning of suan stone unknown.')
    plants(s,[('liu','栁','Liu trees'),('niu','杻','Niu trees'),('tan','檀','Tan trees'),('chu','楮','Chu trees')],'其木多栁杻檀楮')
    forest=add(s,'place','mangfu','莽浮之林','Mangfu forest','其東有林焉名曰莽浮之林多羙木鳥獸','East lies Mangfu forest, with fine trees, birds and beasts.')
    tree=product(s,'fine-wood','羙木（莽浮林）','Fine trees in Mangfu forest','多羙木鳥獸','Fine trees are abundant in Mangfu forest.','plant');LINKS.append((forest,tree))
    for k,n,en in [('birds','鳥','Birds'),('beasts','獸','Beasts')]:
        a=unknown(s,k,n+'（莽浮林泛称）',en+' (Mangfu forest, generic account)','多羙木鳥獸');LINKS.append((forest,a))
    s='r12-fufu';products(s,[('gold','黄金','Gold','其上多黄金','Gold is abundant above.'),('qing-xionghuang','青雄黃','Qing-xionghuang','其下多青雄黃','Qing-xionghuang is abundant below.')]);plants(s,[('mulberry','桑','Mulberry trees'),('chu','楮','Chu trees')],'其木多桑楮');plants(s,[('bamboo','竹','Bamboo'),('jigu','雞皷','Jigu herbs')],'其草多竹雞皷')
    yuer=add(s,'deity','yuer','于兒（夫夫）','Yu-er (Fufu)','神于兒居之其狀人身而身操兩蛇常逰于江淵出入有光','Yu-er has a human body, holds two snakes, frequents the Jiang pool and enters and leaves with light.','人身操两蛇据正文，捕获身操原字照存；图作两手各持一蛇，手位、双臂双腿、衣装面貌配色姿态为艺术解释。','Holding one snake in each of two hands explicitly interprets the captured body-character wording. Arms, legs, clothing, age, face, colors and pose are artistic; no third snake is added.')
    pool=water(s,'jiang-pool','江淵（夫夫）','Jiang pool (Fufu)','常逰于江淵','Yu-er habitually visits the Jiang pool.');LINKS.append((yuer,pool))
